{"command":"cat package.json; cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']
const PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>', '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.']

class ScanError extends Error {
  constructor(pos, reason) { super(reason); this.pos = pos; this.reason = reason }
}

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && /^[A-Za-z]$/.test(c)
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)

function scan(text) {
  const cs = Array.from(text)
  const n = cs.length
  const tokens = []
  // pos[i] = [line, col] of code point i
  const pos = new Array(n + 1)
  let line = 1, col = 1
  for (let i = 0; i < n; i++) {
    pos[i] = [line, col]
    if (cs[i] === '\n') { line++; col = 1 }
    else if (cs[i] === '\t') col = Math.floor((col - 1) / 4) * 4 + 5
    else col++
  }
  pos[n] = [line, col]
  const err = (i, reason) => new ScanError(pos[i], reason)

  let i = 0
  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { i++; continue }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') i++
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      const start = i
      let depth = 1
      i += 2
      while (i < n && depth > 0) {
        if (cs[i] === '/' && cs[i + 1] === '*') { depth++; i += 2 }
        else if (cs[i] === '*' && cs[i + 1] === '/') { depth--; i += 2 }
        else i++
      }
      if (depth > 0) throw err(start, 'unterminated block comment')
      continue
    }
    const start = i
    const at = pos[start]
    if (c === 'r' && cs[i + 1] === '"') {
      let j = i + 2
      while (j < n && cs[j] !== '"') j++
      if (j >= n) throw err(start, 'unterminated string')
      tokens.push({ at, kind: 'rawstring', body: JSON.stringify(cs.slice(i + 2, j).join('')) })
      i = j + 1
      continue
    }
    if (isIdStart(c)) {
      let j = i + 1
      while (j < n && isIdPart(cs[j])) j++
      const w = cs.slice(i, j).join('')
      tokens.push({ at, kind: KEYWORDS.has(w) ? 'keyword' : 'ident', body: w })
      i = j
      continue
    }
    if (isDigit(c)) {
      let j = i
      // digit run: digit (_? digit)*, starting at j which must be a digit
      const run = (ok) => {
        j++
        for (;;) {
          if (ok(cs[j])) j++
          else if (cs[j] === '_' && ok(cs[j + 1])) j += 2
          else break
        }
      }
      let bad = false
      const p = cs[i + 1]
      const radix = c === '0' ? { x: isHex, X: isHex, b: (d) => d === '0' || d === '1', B: (d) => d === '0' || d === '1', o: (d) => d >= '0' && d <= '7' && d.length === 1, O: (d) => d >= '0' && d <= '7' && d.length === 1 }[p] : undefined
      if (radix) {
        j = i + 2
        if (radix(cs[j])) run(radix)
        else bad = true
      } else {
        run(isDigit)
        if (cs[j] === '.' && isDigit(cs[j + 1])) { j++; run(isDigit) }
        if (cs[j] === 'e' || cs[j] === 'E') {
          if (isDigit(cs[j + 1])) { j++; run(isDigit) }
          else if ((cs[j + 1] === '+' || cs[j + 1] === '-') && isDigit(cs[j + 2])) { j += 2; run(isDigit) }
        }
      }
      if (bad || isIdPart(cs[j])) {
        while (j < n && isIdPart(cs[j])) j++
        throw err(start, 'invalid number ' + cs.slice(i, j).join(''))
      }
      tokens.push({ at, kind: 'number', body: cs.slice(i, j).join('') })
      i = j
      continue
    }
    if (c === '"') {
      let j = i + 1
      let val = ''
      for (;;) {
        if (j >= n) throw err(start, 'unterminated string')
        const d = cs[j]
        if (d === '"') { j++; break }
        if (d === '\n') throw err(j, 'newline in string')
        if (d !== '\\') { val += d; j++; continue }
        const e = cs[j + 1]
        if (e === undefined) throw err(start, 'unterminated string')
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', '0': '\0' }
        if (Object.hasOwn(simple, e)) { val += simple[e]; j += 2 }
        else if (e === 'x') {
          if (isHex(cs[j + 2]) && isHex(cs[j + 3])) {
            val += String.fromCharCode(parseInt(cs[j + 2] + cs[j + 3], 16)); j += 4
          } else throw err(j, 'invalid escape \\x')
        } else if (e === 'u') {
          if (cs[j + 2] !== '{') throw err(j, 'invalid escape \\u')
          let k = j + 3
          let h = ''
          while (isHex(cs[k])) h += cs[k++]
          if (!h || cs[k] !== '}') throw err(j, 'invalid escape \\u')
          const v = parseInt(h.replace(/^0+(?=.)/, ''), 16)
          if (h.replace(/^0+/, '').length > 6 || v > 0x10ffff) throw err(j, 'invalid escape \\u')
          val += String.fromCodePoint(v)
          j = k + 1
        } else throw err(j, 'invalid escape \\' + e)
      }
      tokens.push({ at, kind: 'string', body: JSON.stringify(val) })
      i = j
      continue
    }
    const two = c + (cs[i + 1] ?? '')
    if (PUNCT.includes(two)) { tokens.push({ at, kind: 'punct', body: two }); i += 2; continue }
    if (PUNCT.includes(c)) { tokens.push({ at, kind: 'punct', body: c }); i++; continue }
    throw err(i, 'unexpected character ' + c)
  }
  return tokens
}

function main() {
  const mode = process.argv.length === 3 ? process.argv[2] : undefined
  if (mode !== 'tokens' && mode !== 'stats') {
    process.stderr.write('error: usage: cli.js tokens|stats\n')
    process.exit(2)
  }
  const text = readFileSync(0, 'utf8')
  let tokens
  try {
    tokens = scan(text)
  } catch (e) {
    if (!(e instanceof ScanError)) throw e
    process.stderr.write(`error: ${e.pos[0]}:${e.pos[1]}: ${e.reason}\n`)
    process.exit(2)
  }
  let out = ''
  if (mode === 'tokens') {
    for (const t of tokens) out += `${t.at[0]}:${t.at[1]} ${t.kind} ${t.body}\n`
  } else {
    for (const k of KINDS) out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
    out += `total ${tokens.length}\n`
  }
  process.stdout.write(out)
}

main()
