import { readFileSync } from 'node:fs'
import { merge } from './merge.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (!['merge', 'merge2', 'regions'].includes(mode)) {
  process.stderr.write('error: usage: cli.js merge|merge2|regions\n')
  process.exit(2)
}
const lines = readFileSync(0, 'utf8').split('\n')
if (lines[lines.length - 1] === '') lines.pop()
const docs = [[]]
for (const l of lines) {
  if (l === '%%%') docs.push([])
  else docs[docs.length - 1].push(l)
}
if (docs.length !== 3) {
  process.stderr.write('error: expected three parts separated by %%%\n')
  process.exit(2)
}
const regions = merge(docs[0], docs[1], docs[2])
const out = []
let conflict = false
for (const r of regions) {
  if (r.kind === 'conflict') conflict = true
  if (mode === 'regions') {
    out.push(r.kind === 'conflict'
      ? `conflict mine=${r.mine.length} base=${r.base.length} theirs=${r.theirs.length}`
      : `${r.kind} ${r.lines.length}`)
  } else if (r.kind === 'conflict') {
    out.push('<<<<<<< mine', ...r.mine)
    if (mode === 'merge') out.push('||||||| base', ...r.base)
    out.push('=======', ...r.theirs, '>>>>>>> theirs')
  } else out.push(...r.lines)
}
process.stdout.write(out.map(l => l + '\n').join(''))
process.exit(conflict ? 1 : 0)
