cat > src/merge.js <<'EOF'
function changes(base, side, who) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--)
    for (let j = m - 1; j >= 0; j--)
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
  const out = []
  let i = 0, j = 0, cur = null
  const flush = () => { if (cur) { out.push(cur); cur = null } }
  while (i < n || j < m) {
    if (i < n && j < m && base[i] === side[j]) {
      flush(); i++; j++; continue
    }
    if (!cur) cur = { who, bs: i, be: i, ss: j, se: j }
    if (i < n && (j >= m || L[i + 1][j] >= L[i][j + 1])) { i++; cur.be = i } else { j++; cur.se = j }
  }
  flush()
  return out
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

export function merge(mine, base, theirs) {
  const all = [...changes(base, mine, 0), ...changes(base, theirs, 1)]
  all.sort((a, b) => a.bs - b.bs || a.who - b.who)
  const res = []
  let pos = 0, k = 0
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    if (rs > pos) res.push({ kind: 'stable', lines: base.slice(pos, rs) })
    pos = re
    if (group.length === 1) {
      const c = group[0]
      res.push({ kind: c.who ? 'theirs' : 'mine', lines: (c.who ? theirs : mine).slice(c.ss, c.se) })
      continue
    }
    const baseLines = base.slice(rs, re)
    const side = (who, lines) => {
      const g = group.filter(c => c.who === who)
      if (!g.length) return baseLines
      const f = g[0], l = g[g.length - 1]
      return lines.slice(f.ss - (f.bs - rs), l.se + (re - l.be))
    }
