export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((c) => [c, []]))
  const rounds = []
  for (;;) {
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const pick = b.prefs.find((c) => continuing.has(c))
      if (pick === undefined) continue
      votes.set(pick, votes.get(pick) + b.count)
      active += b.count
    }
    let total = 0n
    for (const b of ballots) total += b.count
    for (const [c, v] of votes) history.get(c).push(v)
    const list = [...votes].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : cmp(a[0], b[0])))
    const round = {
      counts: list.map(([n, v]) => [n, v.toString()]),
      exhausted: (total - active).toString(),
      eliminated: null,
    }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    const top = list.find(([, v]) => v * 2n > active)
    if (top) return { rounds, winner: top[0] }
