      const lo = vs.reduce((m, v) => (v < m ? v : m))
      if (vs.every((v) => v === lo)) r++
      else {
        s = s.filter((c) => history.get(c)[r] === lo)
        r = 0
      }
    }
    const out = s.sort(cmp).pop()
    round.eliminated = out
    continuing.delete(out)
  }
}
