  const alive = new Set(cands)
  const hist = new Map(cands.map((c) => [c, []]))
  const out = []
  let winner = null
  let k = 0
  for (;;) {
    k++
    const cnt = new Map([...alive].map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const c = b.prefs.find((p) => alive.has(p))
      if (c !== undefined) { cnt.set(c, cnt.get(c) + b.count); active += b.count }
    }
    let total = 0n
    for (const b of ballots) total += b.count
    for (const c of alive) hist.get(c).push(cnt.get(c))
    const order = [...alive].sort((a, b) => (cnt.get(a) > cnt.get(b) ? -1 : cnt.get(a) < cnt.get(b) ? 1 : a < b ? -1 : a > b ? 1 : 0))
