  const m = /^([^ \t]*)[ \t]*([\s\S]*)$/.exec(s)
  const addrText = m[1]
  const a = parseAddr(addrText)
  if (!a) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${addrText}\n`)
    process.exit(2)
  }
  if (cells.has(a.key)) {
    process.stderr.write(`error: line ${i + 1}: cell ${a.key} is declared twice\n`)
    process.exit(2)
  }
  cells.set(a.key, { col: a.col, row: a.row, key: a.key, content: m[2] })
}

// ---- formula parser
function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const c = src[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length
    } else if ((m = /^(<>|<=|>=|[=<>+\-*\/^(),:])/.exec(src.slice(i)))) {
      toks.push({ t: 'op', v: m[0] }); i += m[0].length
    } else return null
  }
  return toks
}

function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return null
  let p = 0
  const peek = () => toks[p]
  const isOp = (v) => toks[p] && toks[p].t === 'op' && toks[p].v === v
  const fail = () => { throw new Error('syntax') }
  function cmp() {
    let l = add()
    while (peek() && peek().t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(peek().v)) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { k: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { k: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { k: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { k: 'un', op, e: unary() } }
    return primary()
  }
  function arg() {
    // range directly as an argument
    if (peek() && peek().t === 'word' && toks[p + 1] && toks[p + 1].t === 'op' && toks[p + 1].v === ':') {
      const a = toks[p].v
      p += 2
      if (!peek() || peek().t !== 'word') fail()
      const b = toks[p++].v
      return { k: 'range', a, b }
    }
    return cmp()
  }
  function primary() {
    const t = peek()
    if (!t) fail()
    if (t.t === 'num') { p++; return { k: 'num', v: t.v } }
    if (t.t === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) fail()
      p++
      return e
    }
    if (t.t === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++; return { k: 'call', name: t.v.toUpperCase(), args } }
        for (;;) {
          args.push(arg())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          fail()
        }
        return { k: 'call', name: t.v.toUpperCase(), args }
      }
      if (isOp(':')) {
        // range outside a function argument: grammar accepts, evaluates to #ERR!
        p++
        if (!peek() || peek().t !== 'word') fail()
        const b = toks[p++].v
        return { k: 'range', a: t.v, b, misplaced: true }
      }
      const u = t.v.toUpperCase()
      if (u === 'TRUE') return { k: 'bool', v: true }
      if (u === 'FALSE') return { k: 'bool', v: false }
      return { k: 'ref', w: t.v }
    }
    fail()
  }
  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch {
    return null
  }
}

// a misplaced range: mark any range not directly an argument
function markMisplaced(node, direct) {
  if (!node) return
  if (node.k === 'range') { if (!direct) node.misplaced = true; return }
  if (node.k === 'bin') { markMisplaced(node.l, false); markMisplaced(node.r, false) }
  else if (node.k === 'un') markMisplaced(node.e, false)
  else if (node.k === 'call') node.args.forEach((a) => markMisplaced(a, true))
