const memo = new Map()
const active = new Set()

function cellValue(key) {
  if (memo.has(key)) return memo.get(key)
  const c = cells.get(key)
  if (!c) return 0
  if (active.has(key)) return err('#CYCLE!')
  active.add(key)
  let v
  if (c.formula) v = c.ast ? evalNode(c.ast) : err('#ERR!')
  else v = literal(c.content)
  active.delete(key)
  memo.set(key, v)
  return v
}

function literal(s) {
  if (s === '') return 0
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) return Number(s)
  if (ERRS.has(s)) return err(s)
  return s
}

const toNum = (v) => (typeof v === 'number' ? v : typeof v === 'boolean' ? (v ? 1 : 0) : err('#VALUE!'))
const fin = (n) => (Number.isFinite(n) ? n : err('#DIV/0!'))
const rank = (v) => (typeof v === 'number' ? 0 : typeof v === 'string' ? 1 : 2)

