          case '=': return d === 0
          case '<>': return d !== 0
          case '<': return d < 0
          case '<=': return d <= 0
          case '>': return d > 0
          default: return d >= 0
        }
      }
      const a = toNum(l)
      if (isErr(a)) return a
      const b = toNum(r)
      if (isErr(b)) return b
      switch (n.op) {
        case '+': return fin(a + b)
        case '-': return fin(a - b)
        case '*': return fin(a * b)
        case '/': return b === 0 ? err('#DIV/0!') : fin(a / b)
        default: return fin(Math.pow(a, b))
      }
    }
    case 'call': return evalCall(n)
  }
}

function cmpPoints(a, b) {
  const x = [...a], y = [...b]
  for (let i = 0; i < Math.min(x.length, y.length); i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d < 0 ? -1 : 1
  }
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}

// values contributed by one argument (list), or an error
function argValues(a) {
  if (a.k === 'range') {
    const ks = rangeCells(a)
    if (!ks) return [err('#REF!')]
    return ks.map(cellValue)
  }
  return [evalNode(a)]
}

function evalCall(n) {
  const N = n.args.length
  const name = n.name
  const known = ['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF']
  if (!known.includes(name)) return err('#NAME?')
  if (name === 'IF' ? N !== 3 : name === 'ABS' ? N !== 1 : N < 1) return err('#ERR!')
  if (name === 'IF') {
    let c
    if (n.args[0].k === 'range') {
      const vs = argValues(n.args[0])
      if (vs.length !== 1) return err('#ERR!')
      c = vs[0]
    } else c = evalNode(n.args[0])
    if (isErr(c)) return c
    let t
    if (typeof c === 'boolean') t = c
    else if (typeof c === 'number') t = c !== 0
    else return err('#VALUE!')
    const br = n.args[t ? 1 : 2]
    if (br.k === 'range') {
      const vs = argValues(br)
      return vs.length === 1 ? vs[0] : err('#ERR!')
    }
    return evalNode(br)
  }
  const vals = []
  for (const a of n.args) {
    for (const v of argValues(a)) {
      if (isErr(v)) return v
      vals.push(v)
    }
  }
  if (name === 'COUNT') return vals.filter((v) => typeof v === 'number').length
  if (name === 'ABS' && vals.length !== 1) return err('#ERR!')
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (isErr(x)) return x
    nums.push(x)
  }
  switch (name) {
    case 'ABS': return Math.abs(nums[0])
    case 'SUM': return fin(nums.reduce((s, x) => s + x, 0))
    case 'MIN': return nums.length ? Math.min(...nums) : 0
    case 'MAX': return nums.length ? Math.max(...nums) : 0
    case 'AVG': return nums.length ? fin(nums.reduce((s, x) => s + x, 0) / nums.length) : err('#DIV/0!')
  }
}

// ---- deps
function collect(n, set) {
  if (!n) return
  switch (n.k) {
    case 'ref': { const a = parseAddr(n.w); if (a) set.set(a.key, a); break }
    case 'range': {
      const a = parseAddr(n.a), b = parseAddr(n.b)
      if (a && b) {
        for (let c = Math.min(a.col, b.col); c <= Math.max(a.col, b.col); c++)
          for (let r = Math.min(a.row, b.row); r <= Math.max(a.row, b.row); r++) set.set(keyOf(c, r), { col: c, row: r, key: keyOf(c, r) })
      }
      break
    }
    case 'bin': collect(n.l, set); collect(n.r, set); break
    case 'un': collect(n.e, set); break
    case 'call': n.args.forEach((a) => collect(a, set)); break
  }
}

function fmt(v) {
  if (isErr(v)) return v.err
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE'
  if (typeof v === 'number') return String(Number(v.toPrecision(10)))
  return v
}

const sorted = [...cells.values()].sort((a, b) => a.col - b.col || a.row - b.row)
let out = ''
for (const c of sorted) {
  if (mode === 'values') out += `${c.key}=${fmt(cellValue(c.key))}\n`
  else {
    const set = new Map()
    if (c.formula && c.ast) collect(c.ast, set)
    const ds = [...set.values()].sort((a, b) => a.col - b.col || a.row - b.row)
    out += `${c.key}:${ds.map((d) => ' ' + d.key).join('')}\n`
  }
}
process.stdout.write(out)
