}

// ---- parse every cell
for (const c of cells.values()) {
  if (c.content[0] === '=') {
    const ast = parseFormula(c.content.slice(1))
    if (ast) markMisplaced(ast, false)
    c.ast = ast
    c.formula = true
  }
}

// ---- evaluation
const memo = new Map()
const active = new Set()

function cellValue(key) {
  if (memo.has(key)) return memo.get(key)
  const c = cells.get(key)
  if (!c) return 0
  if (active.has(key)) return err('#CYCLE!')
  active.add(key)
  let v
  if (c.formula) v = c.ast ? evalNode(c.ast) : err('#ERR!')
  else v = literal(c.content)
  active.delete(key)
  memo.set(key, v)
  return v
}

function literal(s) {
  if (s === '') return 0
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(s)) return Number(s)
  if (ERRS.has(s)) return err(s)
  return s
}

const toNum = (v) => (typeof v === 'number' ? v : typeof v === 'boolean' ? (v ? 1 : 0) : err('#VALUE!'))
const fin = (n) => (Number.isFinite(n) ? n : err('#DIV/0!'))
const rank = (v) => (typeof v === 'number' ? 0 : typeof v === 'string' ? 1 : 2)

function evalNode(n) {
  switch (n.k) {
    case 'num': return n.v
    case 'bool': return n.v
    case 'ref': {
      const a = parseAddr(n.w)
      return a ? cellValue(a.key) : err('#REF!')
    }
    case 'range': return err('#ERR!')
    case 'un': {
      const v = evalNode(n.e)
      if (isErr(v)) return v
      const x = toNum(v)
      if (isErr(x)) return x
      return n.op === '-' ? fin(-x) : x
    }
    case 'bin': {
      const l = evalNode(n.l)
      const r = evalNode(n.r)
      if (isErr(l)) return l
      if (isErr(r)) return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        let d
        if (rank(l) !== rank(r)) d = rank(l) - rank(r)
