          case '<>': return d !== 0
          case '<': return d < 0
          case '<=': return d <= 0
          case '>': return d > 0
          default: return d >= 0
        }
      }
      const a = toNum(l)
      if (isErr(a)) return a
      const b = toNum(r)
      if (isErr(b)) return b
      switch (n.op) {
        case '+': return fin(a + b)
        case '-': return fin(a - b)
        case '*': return fin(a * b)
        case '/': return b === 0 ? err('#DIV/0!') : fin(a / b)
