    else if (typeof c === 'number') t = c !== 0
    else return err('#VALUE!')
    const br = n.args[t ? 1 : 2]
    if (br.k === 'range') {
      const vs = argValues(br)
      return vs.length === 1 ? vs[0] : err('#ERR!')
    }
    return evalNode(br)
  }
  const vals = []
  for (const a of n.args) {
    for (const v of argValues(a)) {
      if (isErr(v)) return v
      vals.push(v)
    }
  }
