      break
    }
    case 'bin': collect(n.l, set); collect(n.r, set); break
    case 'un': collect(n.e, set); break
    case 'call': n.args.forEach((a) => collect(a, set)); break
  }
}

function fmt(v) {
  if (isErr(v)) return v.err
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE'
  if (typeof v === 'number') return String(Number(v.toPrecision(10)))
  return v
}

const sorted = [...cells.values()].sort((a, b) => a.col - b.col || a.row - b.row)
let out = ''
for (const c of sorted) {
  if (mode === 'values') out += `${c.key}=${fmt(cellValue(c.key))}\n`
  else {
    const set = new Map()
    if (c.formula && c.ast) collect(c.ast, set)
    const ds = [...set.values()].sort((a, b) => a.col - b.col || a.row - b.row)
    out += `${c.key}:${ds.map((d) => ' ' + d.key).join('')}\n`
  }
}
