const lines = text.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cost = new Map()
const deps = new Map()
const depUses = []
lines.forEach((raw, i) => {
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  const n = i + 1
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], BigInt(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    for (const x of w.slice(1)) depUses.push(x)
    if (!deps.has(w[1])) deps.set(w[1], new Set())
    for (const d of w.slice(2)) deps.get(w[1]).add(d)
  } else {
    fail(`error: line ${n}: unknown directive ${w[0]}`)
  }
})
for (const x of depUses) if (!cost.has(x)) fail(`error: unknown task ${x}`)

const names = [...cost.keys()].sort(cmp)
const dl = new Map(names.map((k) => [k, [...(deps.get(k) ?? [])].sort(cmp)]))

// cycle detection
{
  const state = new Map()
  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const v of dl.get(u)) {
      if (state.get(v) === 1) {
        const cyc = stack.slice(stack.indexOf(v)).concat(v)
        fail('error: cycle: ' + cyc.join(' -> '), 3)
      }
      if (!state.has(v)) visit(v)
    }
    stack.pop()
    state.set(u, 2)
  }
  for (const k of names) if (!state.has(k)) visit(k)
}

const start = new Map()
const finish = new Map()
const depth = new Map()
const calc = (u) => {
  if (finish.has(u)) return
  let s = 0n
  let d = 0
  for (const v of dl.get(u)) {
    calc(v)
    if (finish.get(v) > s) s = finish.get(v)
    if (depth.get(v) + 1 > d) d = depth.get(v) + 1
  }
  start.set(u, s)
  finish.set(u, s + cost.get(u))
  depth.set(u, d)
}
names.forEach(calc)
let total = 0n
for (const k of names) if (finish.get(k) > total) total = finish.get(k)

const out = []
if (mode === 'waves') {
  const ws = []
  for (const k of names) (ws[depth.get(k)] ??= []).push(k)
  ws.forEach((w, i) => out.push(`wave ${i}: ${w.join(' ')}`))
  out.push(`total ${total}`)
} else if (mode === 'explain') {
  for (const k of names) out.push(`${k} start=${start.get(k)} finish=${finish.get(k)} depth=${depth.get(k)}`)
  out.push(`total ${total}`)
} else {
  const users = new Map(names.map((k) => [k, []]))
  for (const k of names) for (const d of dl.get(k)) users.get(d).push(k)
  const prio = new Map()
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    let m = 0n
    for (const v of users.get(u)) if (pr(v) > m) m = pr(v)
    prio.set(u, m + cost.get(u))
    return prio.get(u)
  }
  names.forEach(pr)
  const order = [...names].sort((a, b) => (prio.get(a) > prio.get(b) ? -1 : prio.get(a) < prio.get(b) ? 1 : cmp(a, b)))
  const freeAt = Array(workers).fill(0n)
  const runs = Array.from({ length: workers }, () => [])
  const fin = new Map()
  let left = order.length
  let t = 0n
  let makespan = 0n
  while (left > 0) {
    for (;;) {
      const wi = freeAt.findIndex((f) => f <= t)
      if (wi < 0) break
      const task = order.find((k) => !fin.has(k) && dl.get(k).every((d) => fin.has(d) && fin.get(d) <= t))
      if (task === undefined) break
      const f = t + cost.get(task)
      fin.set(task, f)
      freeAt[wi] = f
      runs[wi].push(`${task}@${t}-${f}`)
      if (f > makespan) makespan = f
      left--
    }
    if (left === 0) break
    // next instant: a worker frees up or a running task finishes
    let next = null
    for (const f of fin.values()) if (f > t && (next === null || f < next)) next = f
    t = next
  }
  runs.forEach((r, i) => out.push(`worker ${i}:` + r.map((x) => ' ' + x).join('')))
  out.push(`makespan ${makespan}`)
}
process.stdout.write(out.join('\n') + (out.length ? '\n' : ''))
EOF
