          } else {
            p = { kind: 'w', name: f[1], limit: num(f[2], 'limit', 0), span: num(f[3], 'span', 1) }
          }
          if (policies.has(f[1])) fail(`policy ${f[1]} is declared twice`)
          policies.set(f[1], p)
        }
