/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import { readFileSync } from 'node:fs'

class Fail extends Error {
  constructor(message, code = 2) {
    super(message)
    this.code = code
  }
}

function parseArgs(argv) {
  const usage = new Fail('error: usage: cli.js waves|explain|pack <workers>')
  const [cmd, ...rest] = argv
  if ((cmd === 'waves' || cmd === 'explain') && rest.length === 0) return { cmd }
  if (cmd === 'pack' && rest.length === 1) {
    if (!/^[1-9][0-9]*$/.test(rest[0])) throw new Fail('error: workers must be a positive integer')
    return { cmd, workers: Number(rest[0]) }
  }
  throw usage
}

function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const tasks = new Map()
  const depLines = []
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    if (w[0] === 'task') {
      if (w.length !== 3) throw new Fail(`error: line ${n}: expected task <name> <cost>`)
      if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) throw new Fail(`error: line ${n}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw new Fail(`error: line ${n}: cost must be a non-negative integer`)
      if (tasks.has(w[1])) throw new Fail(`error: line ${n}: task ${w[1]} is declared twice`)
      tasks.set(w[1], { name: w[1], cost: BigInt(w[2]), deps: new Set() })
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw new Fail(`error: line ${n}: expected dep <name> <dependency>...`)
      depLines.push(w.slice(1))
    } else {
      throw new Fail(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  for (const names of depLines) {
    for (const nm of names) if (!tasks.has(nm)) throw new Fail(`error: unknown task ${nm}`)
  }
  for (const [first, ...deps] of depLines) for (const d of deps) tasks.get(first).deps.add(d)
  return tasks
}

const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

function checkCycle(tasks) {
  const state = new Map()
  const stack = []
  const visit = (name) => {
    state.set(name, 1)
    stack.push(name)
    for (const d of [...tasks.get(name).deps].sort(cmp)) {
      const s = state.get(d)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(d))
        cyc.push(d)
        throw new Fail(`error: cycle: ${cyc.join(' -> ')}`, 3)
      }
      if (!s) visit(d)
    }
    stack.pop()
    state.set(name, 2)
  }
  for (const name of [...tasks.keys()].sort(cmp)) if (!state.get(name)) visit(name)
}

function schedule(tasks) {
  const info = new Map()
  const calc = (name) => {
    if (info.has(name)) return info.get(name)
    const t = tasks.get(name)
    let start = 0n
    let depth = 0
    for (const d of t.deps) {
      const x = calc(d)
      if (x.finish > start) start = x.finish
      if (x.depth + 1 > depth) depth = x.depth + 1
    }
    const r = { start, finish: start + t.cost, depth }
    info.set(name, r)
    return r
  }
  for (const n of tasks.keys()) calc(n)
  let total = 0n
  for (const r of info.values()) if (r.finish > total) total = r.finish
  return { info, total }
}

function pack(tasks, workers) {
  const prio = new Map()
  const calc = (name) => {
    if (prio.has(name)) return prio.get(name)
    let best = 0n
    // longest chain beginning at name: computed via dependents
    for (const o of tasks.values()) if (o.deps.has(name)) best = best > calc(o.name) ? best : calc(o.name)
    const p = tasks.get(name).cost + best
    prio.set(name, p)
    return p
  }
  for (const n of tasks.keys()) calc(n)
  const finish = new Map()
  const freeAt = Array(workers).fill(0n)
  const runs = Array.from({ length: workers }, () => [])
  const pending = new Set(tasks.keys())
  let t = 0n
  let makespan = 0n
  while (pending.size) {
    for (;;) {
      const w = freeAt.findIndex((f) => f <= t)
      if (w < 0) break
      let pick = null
      for (const name of pending) {
        let ok = true
        for (const d of tasks.get(name).deps) {
          const f = finish.get(d)
          if (f === undefined || f > t) { ok = false; break }
        }
        if (!ok) continue
        if (pick === null || prio.get(name) > prio.get(pick) || (prio.get(name) === prio.get(pick) && name < pick)) pick = name
      }
      if (pick === null) break
      pending.delete(pick)
      const end = t + tasks.get(pick).cost
      finish.set(pick, end)
      freeAt[w] = end
      runs[w].push(`${pick}@${t}-${end}`)
      if (end > makespan) makespan = end
    }
    if (!pending.size) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    if (next === null) break
