      const line = raw.trim()
      if (line === '' || line.startsWith('#')) continue
      const f = line.split(/\s+/)
      const word = f[0]
      if (!['bucket', 'window', 'route', 'event'].includes(word)) throw new Fail(`unknown directive ${word}`)
      if (word !== 'event' && started) throw new Fail('declarations must come before the first event')
      if (word === 'bucket' || word === 'window') {
        const isB = word === 'bucket'
        const argc = isB ? 5 : 4
        if (f.length !== argc) {
          throw new Fail(isB ? 'expected bucket <name> <capacity> <refill> <per>' : 'expected window <name> <limit> <span>')
        }
        if (!NAME.test(f[1])) throw new Fail(`invalid policy name ${f[1]}`)
        let p
        if (isB) {
          const capacity = int('capacity', f[2], 1)
          const refill = int('refill', f[3], 0)
          const per = int('per', f[4], 1)
          p = { kind: 'bucket', name: f[1], capacity, refill, per }
        } else {
          const limit = int('limit', f[2], 0)
          const span = int('span', f[3], 1)
          p = { kind: 'window', name: f[1], limit, span }
        }
        if (policies.has(f[1])) throw new Fail(`policy ${f[1]} is declared twice`)
        p.states = new Map()
        policies.set(f[1], p)
      } else if (word === 'route') {
        if (f.length < 3) throw new Fail('expected route <prefix> <policy>...')
        if (!NAME.test(f[1])) throw new Fail(`invalid route prefix ${f[1]}`)
        if (routes.has(f[1])) throw new Fail(`prefix ${f[1]} is routed twice`)
        for (const name of f.slice(2)) {
          if (!policies.has(name)) throw new Fail(`unknown policy ${name}`)
        }
        routes.set(f[1], f.slice(2).map((x) => policies.get(x)))
      } else {
        if (f.length !== 3) throw new Fail('expected event <tick> <key>')
        const tick = int('tick', f[1], 0)
        if (!NAME.test(f[2])) throw new Fail(`invalid key ${f[2]}`)
        if (lastTick !== null && tick < lastTick) throw new Fail(`tick ${tick} is before tick ${lastTick}`)
        lastTick = tick
        started = true
        events.push({ tick, key: f[2] })
      }
    }
  } catch (e) {
    if (e instanceof Fail) {
      process.stderr.write(`error: line ${n}: ${e.message}\n`)
      process.exit(2)
    }
    throw e
  }
  return { routes, events }
}

function state(p, key) {
  let s = p.states.get(key)
  if (!s) {
    s = p.kind === 'bucket' ? { n: p.capacity * p.per, last: null } : { ticks: [] }
    p.states.set(key, s)
  }
  return s
}

function advance(p, s, tick) {
  if (p.kind === 'bucket') {
    if (s.last !== null) {
      s.n += p.refill * (tick - s.last)
      const max = p.capacity * p.per
      if (s.n > max) s.n = max
    }
    s.last = tick
  } else {
    const cut = tick - p.span
    s.ticks = s.ticks.filter((t) => t > cut)
