}

const allows = (p, s) => (p.kind === 'bucket' ? s.n >= p.per : BigInt(s.ticks.length) < p.limit)

function record(p, s, tick) {
  if (p.kind === 'bucket') s.n -= p.per
  else s.ticks.push(tick)
}

