const out = []
const counts = new Map()
let totA = 0
let totD = 0
for (const { tick, key } of events) {
  let best = null
  for (const [prefix, list] of routes) {
    if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = { length: prefix.length, list }
  }
  let refused = null
  if (best) {
    const sts = best.list.map((p) => state(p, key))
    best.list.forEach((p, i) => advance(p, sts[i], tick))
    for (let i = 0; i < sts.length; i++) {
      if (!allows(best.list[i], sts[i])) {
        refused = best.list[i]
        break
      }
    }
    if (!refused) best.list.forEach((p, i) => record(p, sts[i], tick))
  }
  const c = counts.get(key) || { a: 0, d: 0 }
  counts.set(key, c)
  if (refused) {
    c.d++
    totD++
    out.push(`${tick} ${key} deny ${refused.name}`)
  } else {
    c.a++
    totA++
    out.push(`${tick} ${key} allow`)
  }
}
if (mode === 'summary') {
  out.length = 0
  for (const k of [...counts.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0))) {
    out.push(`${k} allowed=${counts.get(k).a} denied=${counts.get(k).d}`)
  }
  out.push(`total allowed=${totA} denied=${totD}`)
}
process.stdout.write(out.map((l) => l + '\n').join(''))
"}

