const fail = (m) => { throw new ParseError(m) }
const NAME = /[A-Za-z0-9_-]/
const INT = /^[+-]?[0-9]+(_[0-9]+)*$/
const FLOAT = /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*)?([eE][+-]?[0-9]+(_[0-9]+)*)?$/

const newTable = () => ({ k: 'table', m: new Map(), explicit: false })

class LineParser {
  constructor(s) { this.s = s; this.i = 0 }
  ws() { while (this.s[this.i] === ' ' || this.s[this.i] === '\t') this.i++ }
  // at end of line, or at a comment start
  atEnd() { const c = this.s[this.i]; return c === undefined || c === '#' || c === ';' }

  string(q) {
    const s = this.s
    this.i++
    let out = ''
    for (;;) {
      const c = s[this.i]
      if (c === undefined) fail('unterminated string')
      if (c === q) { this.i++; return out }
      if (q === '"' && c === '\\') {
        const e = s[this.i + 1]
        if (e === undefined) fail('unterminated string')
        const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(map, e)) { out += map[e]; this.i += 2; continue }
        if (e === 'u') {
          const h = s.slice(this.i + 2, this.i + 6)
          if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16)); this.i += 6; continue
        }
        // keep surrogate pairs whole
        fail('invalid escape \\' + String.fromCodePoint(s.codePointAt(this.i + 1)))
      }
      out += c; this.i++
    }
  }

  name() {
    const c = this.s[this.i]
    if (c === '"' || c === "'") return this.string(c)
    const st = this.i
    while (this.i < this.s.length && NAME.test(this.s[this.i])) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.s[this.i] !== '.') { this.i = save; return parts }
      this.i++
      this.ws()
      parts.push(this.name())
    }
  }

  value(prefix) {
    const s = this.s
    const c = s[this.i]
    if (c === undefined || c === ',' || c === ']' || c === '}' || c === '#' || c === ';') fail('expected a value')
    if (c === '"') return { k: 'string', v: this.string('"') }
    if (c === "'") return { k: 'string', v: this.string("'") }
    if (c === '[') return this.array(prefix)
    if (c === '{') return this.inline(prefix)
    const st = this.i
    while (this.i < s.length && !' \t,]};'.includes(s[this.i])) this.i++
    const t = s.slice(st, this.i)
    if (t === 'true') return { k: 'boolean', v: true }
    if (t === 'false') return { k: 'boolean', v: false }
    if (INT.test(t)) return { k: 'integer', v: BigInt(t.replace(/_/g, '')).toString() }
    if (FLOAT.test(t)) return { k: 'float', v: Number(t.replace(/_/g, '')) }
    fail('invalid value ' + t)
  }

  array(prefix) {
    this.i++
    const node = { k: 'array', items: [], aot: false }
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      if (this.s[this.i] === ']') { this.i++; return node }
      node.items.push(this.value(prefix))
      this.ws()
      if (this.atEnd()) fail('unterminated array')
      const c = this.s[this.i]
      if (c === ',') { this.i++; continue }
      if (c === ']') { this.i++; return node }
      fail('trailing text after a value')
    }
  }

  inline(prefix) {
    this.i++
    const t = newTable()
    this.ws()
    if (this.atEnd()) fail('unterminated inline table')
    if (this.s[this.i] === '}') { this.i++; return t }
    for (;;) {
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const keys = this.dotted()
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      if (this.s[this.i] !== '=') fail('expected = in an inline table')
      this.i++
      this.ws()
      const v = this.value([...prefix, ...keys])
      assign(t, prefix, keys, v)
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const c = this.s[this.i]
      if (c === ',') { this.i++; continue }
      if (c === '}') { this.i++; return t }
      fail('trailing text after a value')
    }
  }
}

// Walk the segments (all but the last) from table `t`, creating tables.
function walk(t, base, segs) {
  const path = [...base]
  for (const seg of segs) {
    path.push(seg)
    let n = t.m.get(seg)
    if (n === undefined) { n = newTable(); t.m.set(seg, n) }
    if (n.k === 'array' && n.aot) n = n.items[n.items.length - 1]
    if (n.k !== 'table') fail(`${path.join('.')} is not a table`)
    t = n
  }
  return { t, path }
}

function assign(t, base, keys, v) {
  const w = walk(t, base, keys.slice(0, -1))
  const last = keys[keys.length - 1]
  if (w.t.m.has(last)) fail(`key ${[...w.path, last].join('.')} is defined twice`)
  w.t.m.set(last, v)
}

function header(root, p) {
  const s = p.s
  const dbl = s[p.i + 1] === '['
  p.i += dbl ? 2 : 1
  p.ws()
  const segs = p.dotted()
  p.ws()
  if (p.atEnd()) fail('unterminated table header')
  const need = dbl ? ']]' : ']'
  if (s.slice(p.i, p.i + need.length) !== need) fail('unterminated table header')
  p.i += need.length
  p.ws()
  if (!p.atEnd()) fail('trailing text after a table header')
  const w = walk(root, [], segs.slice(0, -1))
  const last = segs[segs.length - 1]
  const path = [...w.path, last]
  const n = w.t.m.get(last)
  if (dbl) {
    const fresh = newTable()
    if (n === undefined) w.t.m.set(last, { k: 'array', items: [fresh], aot: true })
    else if (n.k === 'array' && n.aot) n.items.push(fresh)
    else fail(`${path.join('.')} is not an array of tables`)
    return { t: fresh, path }
  }
  if (n === undefined) {
    const t = newTable(); t.explicit = true
    w.t.m.set(last, t)
    return { t, path }
  }
  if (n.k !== 'table') fail(`${path.join('.')} is not a table`)
  if (n.explicit) fail(`table ${path.join('.')} is defined twice`)
  n.explicit = true
  return { t: n, path }
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = { t: root, path: [] }
  for (let ln = 0; ln < lines.length; ln++) {
    try {
      const p = new LineParser(lines[ln])
      p.ws()
      const c = p.s[p.i]
      if (c === undefined || c === '#' || c === ';') continue
      if (c === '[') { cur = header(root, p); continue }
      const keys = p.dotted()
      p.ws()
      if (p.s[p.i] !== '=') fail('expected key = value')
      p.i++
      p.ws()
      const v = p.value([...cur.path, ...keys])
      p.ws()
      if (!p.atEnd()) fail('trailing text after a value')
      assign(cur.t, cur.path, keys, v)
    } catch (e) {
      if (e instanceof ParseError) e.message = `line ${ln + 1}: ${e.message}`
      throw e
    }
  }
  return root
}
"}

{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'
import { parse, ParseError } from './parser.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'json' && mode !== 'keys') {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

function cmp(a, b) {
  let i = 0, j = 0
  while (i < a.length && j < b.length) {
    const x = a.codePointAt(i), y = b.codePointAt(j)
    if (x !== y) return x - y
    i += x > 0xffff ? 2 : 1
    j += y > 0xffff ? 2 : 1
  }
  return (a.length - i) - (b.length - j)
}
const sorted = (m) => [...m.entries()].sort((a, b) => cmp(a[0], b[0]))

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1), end = '  '.repeat(ind)
  if (n.k === 'table') {
    if (n.m.size === 0) return '{}'
    return '{\n' + sorted(n.m).map(([k, v]) => `${pad}${JSON.stringify(k)}: ${toJson(v, ind + 1)}`).join(',\n') + '\n' + end + '}'
  }
  if (n.k === 'array') {
    if (n.items.length === 0) return '[]'
    return '[\n' + n.items.map((v) => pad + toJson(v, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  if (n.k === 'integer') return n.v
  return JSON.stringify(n.v)
}

function listKeys(n, path, out) {
  if (n.k === 'table') {
    for (const [k, v] of sorted(n.m)) {
      const p = path === null ? k : `${path}.${k}`
      out.push(`${p} ${v.k}`)
      listKeys(v, p, out)
    }
  } else if (n.k === 'array') {
    n.items.forEach((v, i) => {
      const p = `${path}[${i}]`
      out.push(`${p} ${v.k}`)
      listKeys(v, p, out)
    })
  }
}

let root
try {
  root = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
if (mode === 'json') process.stdout.write(toJson(root, 0) + '\n')
else {
  const out = []
  listKeys(root, null, out)
  process.stdout.write(out.map((l) => l + '\n').join(''))
}
"}

