      const v = this.value([...prefix, ...keys])
      assign(t, prefix, keys, v)
      this.ws()
      if (this.atEnd()) fail('unterminated inline table')
      const c = this.s[this.i]
      if (c === ',') { this.i++; continue }
      if (c === '}') { this.i++; return t }
      fail('trailing text after a value')
    }
  }
}

// Walk the segments (all but the last) from table `t`, creating tables.
function walk(t, base, segs) {
  const path = [...base]
  for (const seg of segs) {
    path.push(seg)
    let n = t.m.get(seg)
    if (n === undefined) { n = newTable(); t.m.set(seg, n) }
    if (n.k === 'array' && n.aot) n = n.items[n.items.length - 1]
    if (n.k !== 'table') fail(`${path.join('.')} is not a table`)
    t = n
  }
  return { t, path }
}

function assign(t, base, keys, v) {
  const w = walk(t, base, keys.slice(0, -1))
  const last = keys[keys.length - 1]
  if (w.t.m.has(last)) fail(`key ${[...w.path, last].join('.')} is defined twice`)
  w.t.m.set(last, v)
}

function header(root, p) {
  const s = p.s
  const dbl = s[p.i + 1] === '['
  p.i += dbl ? 2 : 1
  p.ws()
  const segs = p.dotted()
  p.ws()
  if (p.atEnd()) fail('unterminated table header')
  const need = dbl ? ']]' : ']'
  if (s.slice(p.i, p.i + need.length) !== need) fail('unterminated table header')
  p.i += need.length
  p.ws()
  if (!p.atEnd()) fail('trailing text after a table header')
  const w = walk(root, [], segs.slice(0, -1))
  const last = segs[segs.length - 1]
  const path = [...w.path, last]
  const n = w.t.m.get(last)
  if (dbl) {
    const fresh = newTable()
    if (n === undefined) w.t.m.set(last, { k: 'array', items: [fresh], aot: true })
    else if (n.k === 'array' && n.aot) n.items.push(fresh)
    else fail(`${path.join('.')} is not an array of tables`)
    return { t: fresh, path }
  }
  if (n === undefined) {
    const t = newTable(); t.explicit = true
    w.t.m.set(last, t)
    return { t, path }
  }
  if (n.k !== 'table') fail(`${path.join('.')} is not a table`)
  if (n.explicit) fail(`table ${path.join('.')} is defined twice`)
  n.explicit = true
  return { t: n, path }
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = { t: root, path: [] }
  for (let ln = 0; ln < lines.length; ln++) {
    try {
      const p = new LineParser(lines[ln])
      p.ws()
      const c = p.s[p.i]
      if (c === undefined || c === '#' || c === ';') continue
      if (c === '[') { cur = header(root, p); continue }
      const keys = p.dotted()
      p.ws()
      if (p.s[p.i] !== '=') fail('expected key = value')
      p.i++
      p.ws()
      const v = p.value([...cur.path, ...keys])
      p.ws()
      if (!p.atEnd()) fail('trailing text after a value')
      assign(cur.t, cur.path, keys, v)
    } catch (e) {
      if (e instanceof ParseError) e.message = `line ${ln + 1}: ${e.message}`
      throw e
    }
  }
  return root
}
