try {
  lines.forEach((line, i) => {
    try {
      if (mode === 'normalize') {
        out.push(normalize(parse(line)))
      } else {
        const sp = line.indexOf(' ')
        if (sp < 0) throw new UriError('expected a base and a reference')
        const base = parse(line.slice(0, sp))
        if (base.scheme === undefined) throw new UriError('the base has no scheme')
        out.push(normalize(resolve(base, parse(line.slice(sp + 1)))))
      }
    } catch (e) {
      if (e instanceof UriError) throw new UriError(`line ${i + 1}: ${e.message}`)
      throw e
    }
  })
} catch (e) {
  if (!(e instanceof UriError)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
