cat > src/uri.js <<'EOF'
export class UriError extends Error {}

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export function parse(s) {
  const r = {}
  const m = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#([\s\S]*))?$/.exec(s)
  r.scheme = m[1]
  r.authority = m[2]
  r.path = m[3]
  r.query = m[4]
  r.fragment = m[5]
  return r
}

function splitAuthority(a) {
  let userinfo
  let rest = a
  const at = a.lastIndexOf('@')
  if (at >= 0) {
    userinfo = a.slice(0, at)
    rest = a.slice(at + 1)
  }
  const from = rest.lastIndexOf(']') + 1
  const colon = rest.indexOf(':', from)
  let host = rest
  let port
  if (colon >= 0) {
    host = rest.slice(0, colon)
    port = rest.slice(colon + 1)
  }
  return { userinfo, host, port }
}

function pct(s, what) {
  if (/%(?![0-9A-Fa-f]{2})/.test(s)) throw new UriError(`the ${what} has a truncated percent-encoding`)
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return /[A-Za-z0-9\-._~]/.test(c) ? c : '%' + h.toUpperCase()
  })
}

export function removeDots(path) {
  let inp = path
  let out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const j = inp.indexOf('/', 1)
      const seg = j < 0 ? inp : inp.slice(0, j)
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

export function normalize(r) {
  const scheme = r.scheme === undefined ? undefined : r.scheme.replace(/[A-Z]+/g, (x) => x.toLowerCase())
  // checks happen in the order path, userinfo, host, query, fragment
  let path = pct(r.path, 'path')
  let userinfo, host, port
  if (r.authority !== undefined) {
    const a = splitAuthority(r.authority)
    userinfo = a.userinfo === undefined ? undefined : pct(a.userinfo, 'userinfo')
    host = pct(a.host, 'host').replace(/[A-Z]+/g, (x) => x.toLowerCase())
    port = a.port
    if (port === '' || (scheme !== undefined && DEFAULT_PORTS[scheme] === port)) port = undefined
  }
  const query = r.query === undefined ? undefined : pct(r.query, 'query')
  const fragment = r.fragment === undefined ? undefined : pct(r.fragment, 'fragment')
  path = removeDots(path)
  let s = ''
  if (scheme !== undefined) s += scheme + ':'
  if (r.authority !== undefined) {
    if (path === '') path = '/'
    s += '//' + (userinfo !== undefined ? userinfo + '@' : '') + host + (port !== undefined ? ':' + port : '')
  }
  s += path
  if (query !== undefined) s += '?' + query
  if (fragment !== undefined) s += '#' + fragment
  return s
}

export function resolve(base, ref) {
  if (ref.scheme !== undefined) return { ...ref, path: removeDots(ref.path) }
  if (ref.authority !== undefined) return { ...ref, scheme: base.scheme, path: removeDots(ref.path) }
  const t = { scheme: base.scheme, authority: base.authority, fragment: ref.fragment }
  if (ref.path === '') {
    t.path = base.path
    t.query = ref.query !== undefined ? ref.query : base.query
  } else {
    t.query = ref.query
    if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
    else {
      let merged
      if (base.authority !== undefined && base.path === '') merged = '/' + ref.path
      else {
        const i = base.path.lastIndexOf('/')
        merged = i < 0 ? ref.path : base.path.slice(0, i + 1) + ref.path
      }
      t.path = removeDots(merged)
    }
  }
  return t
}
