  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const map = new Map()
  const cells = []
  lines.forEach((raw, i) => {
    const line = raw.replace(/^[ \t]+/, '')
    if (line === '' || line[0] === '#') return
    const m = /^([^ \t]*)[ \t]*([^]*)$/.exec(line)
    const addrText = m[1]
    const content = m[2]
    const a = parseAddr(addrText)
    if (!a) throw fail(`line ${i + 1}: invalid cell address ${addrText}`)
    if (map.has(a.name)) throw fail(`line ${i + 1}: cell ${a.name} is declared twice`)
    const cell = { addr: a.name, col: a.col, row: a.row, content }
    map.set(a.name, cell)
    cells.push(cell)
  })
