  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v
  const BAD = new Error('bad')

  function range(a, b) { return { t: 'range', a: a.v, b: b.v } }

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { t: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    const t = peek()
    if (!t) throw BAD
    if (t.k === 'num') { p++; return { t: 'lit', v: num(t.v) } }
    if (t.k === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) throw BAD
      p++
      return e
    }
    if (t.k === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++; return { t: 'call', name: t.v.toUpperCase(), args } }
        for (;;) {
          args.push(arg())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          throw BAD
        }
        return { t: 'call', name: t.v.toUpperCase(), args }
      }
      if (isOp(':')) {
        p++
        const t2 = peek()
        if (!t2 || t2.k !== 'word' || isKeyword(t2.v)) throw BAD
        p++
        if (isOp('(')) throw BAD
        if (isKeyword(t.v)) throw BAD
        misplaced = true
        return range(t, t2)
      }
      const u = t.v.toUpperCase()
      if (u === 'TRUE') return { t: 'lit', v: { t: 'bool', v: true } }
      if (u === 'FALSE') return { t: 'lit', v: { t: 'bool', v: false } }
      return { t: 'ref', name: t.v }
    }
