export function parse(s) {
  const r = { scheme: null, authority: null, path: '', query: null, fragment: null }
  let m = /^([^:/?#]+):/.exec(s)
  if (m) { r.scheme = m[1]; s = s.slice(m[0].length) }
  if (s.startsWith('//')) {
    const e = s.slice(2).search(/[/?#]/)
    const end = e < 0 ? s.length : e + 2
    r.authority = s.slice(2, end)
    s = s.slice(end)
  }
  const h = s.indexOf('#')
  if (h >= 0) { r.fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { r.query = s.slice(q + 1); s = s.slice(0, q) }
  r.path = s
  return r
}

export function removeDots(p) {
  let out = ''
  while (p.length) {
    if (p.startsWith('../')) p = p.slice(3)
    else if (p.startsWith('./')) p = p.slice(2)
    else if (p.startsWith('/./')) p = p.slice(2)
    else if (p === '/.') p = '/'
    else if (p.startsWith('/../') || p === '/..') {
      p = p === '/..' ? '/' : p.slice(3)
      out = out.slice(0, out.lastIndexOf('/') < 0 ? 0 : out.lastIndexOf('/'))
    } else if (p === '.' || p === '..') p = ''
    else {
      const i = p.indexOf('/', 1)
      const seg = i < 0 ? p : p.slice(0, i)
      out += seg
      p = p.slice(seg.length)
    }
  }
  return out
}

function splitAuth(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at < 0 ? null : a.slice(0, at)
  const hp = a.slice(at + 1)
  const c = hp.indexOf(':', hp.lastIndexOf(']') + 1)
  return c < 0 ? { userinfo, host: hp, port: null } : { userinfo, host: hp.slice(0, c), port: hp.slice(c + 1) }
}

const UNRESERVED = /^[A-Za-z0-9\-._~]$/
function pct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const c = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(c) ? c : '%' + h.toUpperCase()
  })
}
const bad = (s) => /%(?![0-9A-Fa-f]{2})/.test(s)
const lower = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())
const DEFAULT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

export class UriError extends Error {}

export function serialize(r) {
  let o = ''
  if (r.scheme !== null) o += r.scheme + ':'
  if (r.authority !== null) o += '//' + r.authority
  o += r.path
  if (r.query !== null) o += '?' + r.query
  if (r.fragment !== null) o += '#' + r.fragment
  return o
}

export function normalize(r) {
