  const checks = [['path', r.path], ['userinfo', a && a.userinfo], ['host', a && a.host], ['query', r.query], ['fragment', r.fragment]]
  for (const [name, v] of checks) {
    if (v != null && bad(v)) throw new UriError(`the ${name} has a truncated percent-encoding`)
  }
