  let path = removeDots(pct(r.path))
  if (authority !== null && path === '') path = '/'
  return serialize({
    scheme, authority, path,
    query: r.query === null ? null : pct(r.query),
    fragment: r.fragment === null ? null : pct(r.fragment),
  })
}

export function resolve(base, ref) {
  if (ref.scheme !== null) return { ...ref, path: removeDots(ref.path) }
  const t = { scheme: base.scheme, authority: null, path: '', query: null, fragment: ref.fragment }
  if (ref.authority !== null) {
    t.authority = ref.authority; t.path = removeDots(ref.path); t.query = ref.query
